const V = "2026-11-20";
const REG = "Registrar/editar: Administrador, Gerente, Gestor e Colaborador. Perfil Leitura apenas consulta. A autoridade é o banco (RLS por projeto, regra única acc_project_tier); a tela só reflete.";
const MAN = "Exige perfil de gestão: Administrador, Gerente ou Gestor. A autoridade é o banco (RLS e RPC).";

type Extra = Partial<Omit<FeatureHelpDefinition, "id" | "title" | "shortDescription" | "description" | "kind" | "module" | "version">>;
const h = (id: string, kind: HelpElementKind, title: string, shortDescription: string, description: string, extra: Extra = {}): FeatureHelpDefinition => ({
  id,
  kind,
  module: "garantias",
  version: V,
  title,
  shortDescription,
  description,
  ...extra,
});

const kpi = (id: string, title: string, short: string, description: string, formula: string, source: string, unit: string, missingData: string): FeatureHelpDefinition =>
  h(id, "kpi", title, short, description, {
    formula,
    source,
    unit,
    refresh: "A cada abertura ou recarga da tela (leitura direta sob RLS; sem cache).",
    missingData,
  });

const field = (id: string, title: string, short: string, description: string, extra: Extra = {}) => h(id, "field", title, short, description, { permissions: REG, ...extra });
const btn = (id: string, title: string, short: string, description: string, extra: Extra = {}) => h(id, "button", title, short, description, extra);
const tab = (id: string, title: string, short: string, description: string, extra: Extra = {}) => h(id, "tab", title, short, description, extra);

